// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/readyz", wrapper.Ready)
	m.HandleFunc("GET "+options.BaseURL+"/v1/backups", wrapper.ListBackups)
	m.HandleFunc("POST "+options.BaseURL+"/v1/backups", wrapper.CreateBackup)
	m.HandleFunc("GET "+options.BaseURL+"/v1/backups/{backupId}", wrapper.ReadBackup)
	m.HandleFunc("GET "+options.BaseURL+"/v1/backups/{backupId}/download", wrapper.StreamPortableBackup)
	m.HandleFunc("POST "+options.BaseURL+"/v1/backups/{backupId}:download", wrapper.AuthorizeBackupDownload)
	m.HandleFunc("POST "+options.BaseURL+"/v1/backups:import", wrapper.ImportPortableBackup)
	m.HandleFunc("POST "+options.BaseURL+"/v1/barriers", wrapper.AcquireBarrier)
	m.HandleFunc("POST "+options.BaseURL+"/v1/barriers/{barrierId}:release", wrapper.ReleaseBarrier)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/git-remote", wrapper.ConfigureRemote)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/local-backup-schedule", wrapper.ScheduleLocalBackup)
	m.HandleFunc("POST "+options.BaseURL+"/v1/mirrors", wrapper.BuildMirror)
	m.HandleFunc("GET "+options.BaseURL+"/v1/mirrors/status", wrapper.ReadMirrorStatus)
	m.HandleFunc("POST "+options.BaseURL+"/v1/mirrors/{mirrorId}:sync", wrapper.SyncMirror)
	m.HandleFunc("POST "+options.BaseURL+"/v1/restores", wrapper.CreateRestore)
	m.HandleFunc("GET "+options.BaseURL+"/v1/restores/{restoreId}/archives/{owner}", wrapper.ServeRestoreArchive)
	m.HandleFunc("GET "+options.BaseURL+"/v1/restores/{restoreId}/progress", wrapper.ReadRestoreProgress)
	m.HandleFunc("POST "+options.BaseURL+"/v1/restores/{restoreId}:abort", wrapper.AbortRestore)
	m.HandleFunc("POST "+options.BaseURL+"/v1/restores/{restoreId}:cleanup", wrapper.CleanupRestore)
	m.HandleFunc("POST "+options.BaseURL+"/v1/restores/{restoreId}:continue", wrapper.ContinueRestore)
	m.HandleFunc("POST "+options.BaseURL+"/v1/restores:validate", wrapper.ValidateRestore)
	m.HandleFunc("GET "+options.BaseURL+"/v1/settings", wrapper.ReadProtectionSettings)
	m.HandleFunc("POST "+options.BaseURL+"/v1/setup:restore", wrapper.RestoreDuringSetup)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:discard", wrapper.DiscardSnapshot)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:export", wrapper.ExportSnapshot)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:stage", wrapper.StageSnapshot)

	return m
}

